(()=>{'use strict';const gallery=document.querySelector('.people-gallery'),cards=[...gallery.querySelectorAll('.person-card')],reduce=matchMedia('(prefers-reduced-motion:reduce)');let active=3;function choose(index,scroll=false){active=index;cards.forEach((c,i)=>{c.classList.toggle('is-active',i===index);c.setAttribute('aria-expanded',String(i===index))});if(scroll&&innerWidth<=700){setTimeout(()=>gallery.scrollTo({left:cards[index].offsetLeft-gallery.offsetLeft-24,behavior:reduce.matches?'instant':'smooth'}),reduce.matches?0:650)}}cards.forEach((card,i)=>{card.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')choose(i)});card.addEventListener('focus',()=>choose(i));card.addEventListener('click',()=>choose(i,true));card.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%cards.length;else if(e.key==='ArrowLeft')next=(i+cards.length-1)%cards.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=cards.length-1;else return;e.preventDefault();cards[next].focus({preventScroll:true});choose(next,true)})});if(innerWidth<=700)choose(0);})();
